def fibonacci_sequence(n):
    """
    Generate the Fibonacci sequence up to the n-th term using recursion.

    Parameters:
    n (int): The number of terms in the Fibonacci sequence to generate.

    Returns:
    list: A list containing the Fibonacci sequence up to the n-th term.
    """
    def fib_recursive(k):
        if k <= 0:
            return 0
        elif k == 1:
            return 1
        else:
            return fib_recursive(k - 1) + fib_recursive(k - 2)

    return [fib_recursive(i) for i in range(n)]
