import json

def flatten_json(json_str):
    """
    Flattens a nested dictionary represented as a JSON string into a flat dictionary.

    Parameters:
    json_str (str): A JSON string representing a nested dictionary.

    Returns:
    dict: A flat dictionary with concatenated keys representing the path to each value.
    """
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    data = json.loads(json_str)
    return _flatten(data)

