def power_by_squaring(x, n):
    """
    Calculate x raised to the power of n using the exponentiation by squaring method.

    Parameters:
    x (float): The base number.
    n (int): The exponent.

    Returns:
    float: The result of x raised to the power of n.
    """
    if n == 0:
        return 1
    elif n < 0:
        return power_by_squaring(1 / x, -n)
    elif n % 2 == 0:
        return power_by_squaring(x * x, n // 2)
    else:
        return x * power_by_squaring(x * x, (n - 1) // 2)
