def find_odd_occurrences(numbers):
    """
    Returns a list of integers that occur an odd number of times in the input list.
    The order of the elements in the output list is the same as their first occurrence in the input list.

    :param numbers: List of integers
    :return: List of integers with odd occurrences
    """
    count_map = {}
    for num in numbers:
        if num in count_map:
            count_map[num] += 1
        else:
            count_map[num] = 1

    result = []
    for num in numbers:
        if count_map[num] % 2 != 0 and num not in result:
            result.append(num)

    return result
