        """Initialize an empty inventory."""
        self.items = {}

    def add_item(self, item, quantity):
        """
        Add a specified quantity of an item to the inventory.
        If the item already exists, update its quantity.

        :param item: The name of the item to add.
        :param quantity: The quantity of the item to add.
        """
        if item in self.items:
            self.items[item] += quantity
        else:
            self.items[item] = quantity

    def remove_item(self, item, quantity):
        """
        Remove a specified quantity of an item from the inventory.
        If the quantity to remove exceeds the available quantity, set the item's quantity to zero.

        :param item: The name of the item to remove.
        :param quantity: The quantity of the item to remove.
        """
        if item in self.items:
            if self.items[item] > quantity:
                self.items[item] -= quantity
            else:
                self.items[item] = 0

    def get_inventory(self):
        """
        Return a dictionary representing the current state of the inventory.

        :return: A dictionary with items as keys and their respective quantities as values.
        """
        return self.items
