import argparse

def parse_arguments():
    """
    Parses command-line arguments for CSV file path, configuration file path, and output JSON file path.
    """
    parser = argparse.ArgumentParser(description='Read CSV and convert to JSON while preserving data types.')
    parser.add_argument('--csv', required=True, help='Input CSV file path')
    parser.add_argument('--config', required=True, help='Configuration JSON file path')
    parser.add_argument('--json', required=True, help='Output JSON file path')
    return parser.parse_args()

def read_config(config_file):
    """
    Reads the configuration JSON file and returns the configuration dictionary.
    """
    with open(config_file, 'r') as f:
        config = json.load(f)
    return config

def convert_value(value, column_name, config):
    """
    Converts a CSV value to the appropriate data type based on the configuration.
    """
    data_type = config.get(column_name, 'str')  # default to string if not specified
    if data_type == 'int':
        try:
            return int(value)
        except ValueError:
            return None
    elif data_type == 'float':
        try:
            return float(value)
        except ValueError:
            return None
    elif data_type == 'Decimal':
        try:
            return Decimal(value)
        except ValueError:
            return None
    else:  # Default to string
        return value

def csv_to_json(csv_file, json_file, config):
    """
    Converts a CSV file to a JSON file while preserving the data types specified in the configuration.
    """
    with open(csv_file, mode='r', newline='', encoding='utf-8') as f_in, open(json_file, mode='w', encoding='utf-8') as f_out:
        reader = csv.DictReader(f_in)
        data = []
        for row in reader:
            converted_row = {k: convert_value(v, k, config) for k, v in row.items()}
            data.append(converted_row)
        json.dump(data, f_out, indent=4)

if __name__ == '__main__':
    args = parse_arguments()
    config = read_config(args.config)
    csv_to_json(args.csv, args.json, config)
