import json

def serialize_object(obj):
    """
    Serializes a given object into a JSON string. If the object has a 'to_dict' method,
    it uses this method to convert the object to a dictionary before serialization.
    Otherwise, it uses the object's '__dict__' attribute.

    :param obj: The object to be serialized.
    :return: A JSON string representing the object.
    """
    def obj_to_dict(obj):
        if hasattr(obj, 'to_dict') and callable(obj.to_dict):
            return obj.to_dict()
        return obj.__dict__

    class CustomEncoder(json.JSONEncoder):
        def default(self, o):
            return obj_to_dict(o)

    return json.dumps(obj, cls=CustomEncoder)
