def is_prime(n, prime_cache={}):
    """Check if a number is prime using memoization for efficiency."""
    if n < 2:
        return False
    if n not in prime_cache:
        if n == 2 or n == 3:
            prime_cache[n] = True
        elif n % 2 == 0 or n % 3 == 0:
            prime_cache[n] = False
        else:
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    prime_cache[n] = False
                    return False
                i += 6
            prime_cache[n] = True
    return prime_cache[n]

def filter_primes(lst):
    """Return a list of prime numbers from the input list."""
    return [x for x in lst if is_prime(x)]
