def classify_numbers(numbers):
    """
    Classifies a list of integers into even, odd, and prime numbers.

    Parameters:
    numbers (list of int): A list of integers to be classified.

    Returns:
    dict: A dictionary with keys 'even', 'odd', and 'prime', each mapping to a list of integers.
    """
    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    result = {'even': [], 'odd': [], 'prime': []}

    for number in numbers:
        if number % 2 == 0:
            result['even'].append(number)
        else:
            result['odd'].append(number)

        if is_prime(number):
            result['prime'].append(number)

    return result
