def longest_increasing_subsequence(nums):
    """
    Finds the length of the longest increasing subsequence in the list using dynamic programming.

    :param nums: List of integers
    :return: Length of the longest increasing subsequence
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
