def is_balanced(expression: str) -> bool:
    """
    Check if the given expression has balanced parentheses.

    :param expression: A string containing characters including parentheses, braces, and brackets.
    :return: True if the expression is balanced, False otherwise.
    """
    stack = []
    matching_parentheses = {')': '(', '}': '{', ']': '['}
    opening_parentheses = set(matching_parentheses.values())

    for char in expression:
        if char in opening_parentheses:
            stack.append(char)
        elif char in matching_parentheses:
            if not stack or stack[-1] != matching_parentheses[char]:
                return False
            stack.pop()

    return not stack
