class PrimeChecker:
    def is_prime(self, x):
        """Return True if x is a prime number, False otherwise."""
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    def next_prime(self, n):
        """Return the next prime number after n."""
        candidate = n + 1
        while not self.is_prime(candidate):
            candidate += 1
        return candidate
