def convert_temperature(temp, unit):
    """
    Converts a given temperature from Fahrenheit to Celsius or vice versa.

    Parameters:
    temp (str or float): The temperature value to convert.
    unit (str): The original unit of the temperature ('F' for Fahrenheit, 'C' for Celsius).

    Returns:
    float: The converted temperature.
    str: Error message if input is invalid.
    """
    try:
        temp = float(temp)
        if unit.upper() == 'F':
            return (temp - 32) * 5.0 / 9.0
        elif unit.upper() == 'C':
            return (temp * 9.0 / 5.0) + 32
        else:
            raise ValueError("Invalid unit. Please use 'F' for Fahrenheit or 'C' for Celsius.")
    except ValueError as e:
        return str(e)
