def find_prime_factors(n):
    """
    Returns a list of distinct prime factors of the given integer n in ascending order.

    :param n: Integer to find the prime factors of.
    :return: List of distinct prime factors of n.
    """
    if n < 2:
        return []

    import math
    sieve_limit = int(math.sqrt(n)) + 1
    is_prime = [True] * sieve_limit
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(math.sqrt(sieve_limit)) + 1):
        if is_prime[start]:
            for multiple in range(start*start, sieve_limit, start):
                is_prime[multiple] = False

    primes = [num for num, prime in enumerate(is_prime) if prime]

    prime_factors = set()
    for prime in primes:
        while n % prime == 0:
            prime_factors.add(prime)
            n //= prime

    if n > 1:
        prime_factors.add(n)

    return sorted(prime_factors)

