def swap_keys_values(input_dict):
    """
    Swaps keys and values in the given dictionary. If a value appears more than once,
    the new dictionary maps that value to a list of keys.

    :param input_dict: Dictionary with unique keys and integer values.
    :return: A new dictionary with values as keys and keys as values or list of keys.
    """
    swapped_dict = {}
    for key, value in input_dict.items():
        if value not in swapped_dict:
            swapped_dict[value] = key
        else:
            if not isinstance(swapped_dict[value], list):
                swapped_dict[value] = [swapped_dict[value]]
            swapped_dict[value].append(key)
    return swapped_dict
