def get_prime_factors(n):
    """
    Returns a list of distinct prime factors of the given integer n in ascending order.

    :param n: An integer (1 ≤ n ≤ 10^6)
    :return: A list of integers representing the distinct prime factors of n in ascending order.
    """
    i = 2
    factors = set()
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.add(i)
    if n > 1:
        factors.add(n)
    return sorted(factors)
