class ListNode:
    def __init__(self, value=0, next=None):
        self.value = value
        self.next = next

def remove_duplicates(head):
    """
    Removes all duplicate values from the linked list, retaining only the first occurrence of each value.

    :param head: ListNode, the head of the linked list
    :return: ListNode, the head of the modified linked list with duplicates removed
    """
    if not head:
        return None

    current = head
    seen_values = {current.value}
    while current.next:
        if current.next.value in seen_values:
            current.next = current.next.next
        else:
            seen_values.add(current.next.value)
            current = current.next

    return head
