def factorial(n):
    """
    Computes the factorial of a non-negative integer n using recursion.

    Parameters:
    n (int): The non-negative integer for which the factorial is to be computed.

    Returns:
    int or None: The factorial of n if n is a non-negative integer, otherwise None.
    """
    if n is None or isinstance(n, float) or (isinstance(n, int) and n < 0):
        return None
    elif n == 0:
        return 1
    else:
        return n * factorial(n - 1)
