def roman_to_int(s: str) -> int:
    """
    Convert a Roman numeral string to an integer.

    :param s: A string representing a Roman numeral (both uppercase and lowercase are allowed).
    :return: The integer value corresponding to the Roman numeral.
    """
    roman_to_value = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000,
        'i': 1, 'v': 5, 'x': 10, 'l': 50, 'c': 100, 'd': 500, 'm': 1000
    }

    result = 0

    for i in range(len(s)):
        if i + 1 < len(s) and roman_to_value[s[i]] < roman_to_value[s[i + 1]]:
            result -= roman_to_value[s[i]]
        else:
            result += roman_to_value[s[i]]

    return result
