class TreeNode:
    def __init__(self, value):
        """
        Initialize a new TreeNode with the given value.
        """
        self.value = value
        self.left = None
        self.right = None

    def insert(self, value):
        """
        Insert a value into the BST. If the value already exists, it is inserted into the right subtree.
        """
        if value < self.value:
            if self.left is None:
                self.left = TreeNode(value)
            else:
                self.left.insert(value)
        else:  # value >= self.value, handle duplicates by going right
            if self.right is None:
                self.right = TreeNode(value)
            else:
                self.right.insert(value)

    def search(self, value):
        """
        Search for a value in the BST. Return True if found, otherwise False.
        """
        if value == self.value:
            return True
        elif value < self.value:
            if self.left is None:
                return False
            return self.left.search(value)
        else:  # value > self.value
            if self.right is None:
                return False
            return self.right.search(value)

    def inorder_traversal(self):
        """
        Perform an in-order traversal of the BST and return the elements in a sorted list.
        """
        elements = []
        if self.left is not None:
            elements += self.left.inorder_traversal()
        elements.append(self.value)
        if self.right is not None:
            elements += self.right.inorder_traversal()
        return elements
