import json

def find_value_by_key(json_data, target_key):
    """
    Recursively searches through a JSON object for a given key and returns its value if found.

    :param json_data: A JSON string representing a nested object.
    :param target_key: The key to search for in the JSON object.
    :return: The value associated with the target key if it exists, otherwise None.
    """
    def search(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == target_key:
                    return value
                result = search(value)
                if result is not None:
                    return result
        elif isinstance(obj, list):
            for item in obj:
                result = search(item)
                if result is not None:
                    return result
        return None

    data = json.loads(json_data)
    return search(data)

