import math

def find_closest_pair_of_points(points):
    """
    Finds and returns the pair of points that are closest to each other from a list of points.

    :param points: List of tuples, where each tuple represents a point (x, y).
    :return: Tuple containing the two closest points in the same order as they appear in the input list.
    """
    def distance(point1, point2):
        return math.sqrt((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2)

    min_distance = float('inf')
    closest_pair = None

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            current_distance = distance(points[i], points[j])
            if current_distance < min_distance:
                min_distance = current_distance
                closest_pair = (points[i], points[j])

    return closest_pair
