def check_braces_balance(expression):
    """
    Determines if the braces in the given expression are balanced.

    :param expression: A string containing various characters including braces.
    :return: True if the braces are balanced, False otherwise.
    """
    stack = []
    brace_map = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in brace_map.values():
            stack.append(char)
        elif char in brace_map.keys():
            if not stack or brace_map[char] != stack.pop():
                return False

    return not stack
