def is_valid_parentheses(s: str) -> bool:
    """
    Determines if the input string s contains a valid sequence of parentheses.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is a valid sequence of parentheses, otherwise False.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

