def log_function_calls(func):
    """
    Decorator that logs the function name and its arguments each time the function is called.
    """
    def wrapper(*args, **kwargs):
        arg_values = ', '.join([repr(arg) for arg in args] + [f"{key}={value!r}" for key, value in kwargs.items()])
        print(f"Calling: {func.__name__}({arg_values})")
        return func(*args, **kwargs)
    return wrapper

@log_function_calls
def factorial(n):
