def find_mode(numbers):
    """
    Returns the mode(s) of a list of integers.

    :param numbers: List of integers.
    :return: List of integers representing the mode(s).
    """
    frequency_dict = {}
    max_frequency = 0

    for number in numbers:
        if number in frequency_dict:
            frequency_dict[number] += 1
        else:
            frequency_dict[number] = 1

        if frequency_dict[number] > max_frequency:
            max_frequency = frequency_dict[number]

    modes = [number for number, frequency in frequency_dict.items() if frequency == max_frequency]

    return modes
