def convert_temperature(temperature, scale):
    """
    Convert the given temperature between Celsius, Fahrenheit, and Kelvin based on the scale provided.

    Parameters:
    - temperature: The temperature value to be converted (float).
    - scale: A string representing the conversion scale ('CtoF', 'FtoC', 'CtoK', 'KtoC', 'FtoK', or 'KtoF').

    Returns:
    - The converted temperature rounded to two decimal places (float).

    Raises:
    - ValueError: If the scale is not one of the specified conversion types.
    """
    if scale == 'CtoF':
        converted = (temperature * 9/5) + 32
    elif scale == 'FtoC':
        converted = (temperature - 32) * 5/9
    elif scale == 'CtoK':
        converted = temperature + 273.15
    elif scale == 'KtoC':
        converted = temperature - 273.15
    elif scale == 'FtoK':
        converted = (temperature - 32) * 5/9 + 273.15
    elif scale == 'KtoF':
        converted = (temperature - 273.15) * 9/5 + 32
    else:
        raise ValueError("Invalid scale. Please use 'CtoF', 'FtoC', 'CtoK', 'KtoC', 'FtoK', or 'KtoF'.")

    return round(converted, 2)
