def calculate_average_transaction_amount_by_customer(transactions):
    """
    Calculate the average transaction amount for each customer from a list of transactions.

    :param transactions: List of tuples, where each tuple contains (transaction_id, customer_id, transaction_amount)
    :return: Dictionary with customer IDs as keys and their average transaction amounts as values
    """
    customer_sums = {}
    customer_counts = {}

    for transaction_id, customer_id, transaction_amount in transactions:
        if customer_id not in customer_sums:
            customer_sums[customer_id] = 0
            customer_counts[customer_id] = 0

        customer_sums[customer_id] += transaction_amount
        customer_counts[customer_id] += 1

