def find_prime_factors(n):
    """
    Returns a list of prime factors of the given integer n in ascending order, including repeated factors.

    :param n: Integer to find the prime factors of.
    :return: List of integers representing the prime factors of n.
    """
    def prime_factorization(number):
        i = 2
        factors = []
        while i * i <= number:
            if number % i:
                i += 1
            else:
                number //= i
                factors.append(i)
        if number > 1:
            factors.append(number)
        return factors

    return prime_factorization(n)
