def encrypt_caesar_cipher(plaintext, shift):
    """
    Encrypts the given plaintext using the Caesar cipher technique.

    Parameters:
    plaintext (str): The string to be encrypted.
    shift (int): The number of positions to shift each letter.

    Returns:
    str: The encrypted string.
    """
    def shift_char(c, shift):
        if c.isalpha():
            start = ord('A') if c.isupper() else ord('a')
            return chr((ord(c) - start + shift) % 26 + start)
        else:
            return c

    return ''.join(shift_char(c, shift) for c in plaintext)
