def calculate_fibonacci(n, memo=None):
    """
    Calculate the nth Fibonacci number using memoization to optimize recursive calls.

    :param n: An integer representing the position in the Fibonacci sequence.
    :param memo: A dictionary to store previously computed Fibonacci numbers.
    :return: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        memo[n] = calculate_fibonacci(n-1, memo) + calculate_fibonacci(n-2, memo)
        return memo[n]
