    Swaps the keys and values of the input dictionary. If multiple keys have the same value,
    they are grouped into a list and used as the value in the new dictionary.

    :param input_dict: Dictionary with unique keys.
    :return: Dictionary with keys and values swapped.
    """
    swapped_dict = {}
    for key, value in input_dict.items():
        if value in swapped_dict:
            if isinstance(swapped_dict[value], list):
                swapped_dict[value].append(key)
            else:
