def validate_brackets(s: str) -> bool:
    """
    Determines if a string of brackets is valid based on the following rules:
    1. Open brackets must be closed by the same type of brackets.
    2. Open brackets must be closed in the correct order.
    3. Every closing bracket must have a corresponding opening bracket.

    :param s: A string consisting of '(', ')', '{', '}', '[' and ']'.
    :return: True if the string is valid, otherwise False.
    """
    matching_bracket = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False
        else:
            return False

    return not stack
