class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a new value into the BST, avoiding duplicates."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper method to insert a new value recursively."""
        if key == node.val:
            return
        elif key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def search(self, key):
        """Search for a value in the BST and return True if found, otherwise False."""
        return self._search(self.root, key)

    def _search(self, node, key):
        """Helper method to search for a value recursively."""
        if node is None or node.val == key:
            return node is not None
        if key > node.val:
            return self._search(node.right, key)
        return self._search(node.left, key)

    def inorder_traversal(self):
        """Perform an in-order traversal of the BST and return the values in a list."""
        result = []
        self._inorder_traversal(self.root, result)
        return result

    def _inorder_traversal(self, node, result):
        """Helper method to perform in-order traversal recursively."""
        if node:
            self._inorder_traversal(node.left, result)
            result.append(node.val)
            self._inorder_traversal(node.right, result)
