def calculate_average_ratings(ratings):
    """
    Calculate the average ratings for each movie from a dictionary of user ratings.

    :param ratings: A dictionary where keys are user IDs and values are dictionaries of movie IDs and their ratings.
    :return: A dictionary with movie IDs as keys and their average ratings as values.
    """
    movie_ratings = {}

    for user_id, movie_dict in ratings.items():
        for movie_id, rating in movie_dict.items():
            if movie_id not in movie_ratings:
                movie_ratings[movie_id] = {'total_rating': 0, 'rating_count': 0}
            movie_ratings[movie_id]['total_rating'] += rating
