def count_duplicates(s):
    """
    Returns a dictionary with characters that appear more than once in the string
    as keys and their counts as values.

    :param s: Input string
    :return: Dictionary of duplicate characters and their counts
    """
    # Dictionary to hold the count of each character
    char_count = {}

    # Loop through each character in the string
    for char in s:
        # Increment count of the character in the dictionary
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Dictionary to hold characters that appear more than once
    duplicates = {}

    # Loop through the character count dictionary
    for char, count in char_count.items():
        # If character count is more than one, add to duplicates dictionary
        if count > 1:
            duplicates[char] = count

    return duplicates

