def generate_html_table(data):
    """
    Generates an HTML table from a list of dictionaries.

    Parameters:
    data (list): A list of dictionaries where each dictionary represents a row in the table.

    Returns:
    str: A string containing the HTML code for the table or an error message.
    """
    try:
        if not data or not isinstance(data, list):
            return "<p>Error: Data is empty or not a list.</p>"

        headers = data[0].keys()
        for item in data:
            if not isinstance(item, dict):
                return "<p>Error: Each item in data should be a dictionary.</p>"
            if set(headers) != set(item.keys()):
                return "<p>Error: Each dictionary must have the same keys.</p>"

        html = "<table border='1'>\n"
        html += "  <tr>\n"
        for header in headers:
            html += f"	<th>{header}</th>\n"
        html += "  </tr>\n"

        for item in data:
            html += "  <tr>\n"
            for value in item.values():
                html += f"	<td>{value}</td>\n"
            html += "  </tr>\n"

        html += "</table>"
        return html
    except Exception as e:
        return f"<p>Error: An unexpected error occurred - {str(e)}</p>"
