def convert_to_lowercase(input_dict):
    """
    Converts all keys in the input dictionary to lowercase. If a value is a string,
    it converts it to lowercase. If a value is a list, it converts all elements
    in the list to lowercase. If a value is a dictionary, it recursively processes
    it in the same manner. All other data types remain unchanged.

    :param input_dict: Dictionary with keys and values of various data types.
    :return: A new dictionary with keys and string values converted to lowercase.
    """
    def lower_value(value):
        if isinstance(value, dict):
            return convert_to_lowercase(value)
        elif isinstance(value, list):
            return [lower_value(item) for item in value]
        elif isinstance(value, str):
            return value.lower()
        else:
            return value

    return {key.lower(): lower_value(value) for key, value in input_dict.items()}
