def flatten_json(json_obj, parent_key='', result=None):
    """
    Flattens a nested JSON object into a one-level dictionary with dot-separated keys.

    :param json_obj: The nested JSON object to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param result: The resulting flat dictionary (used internally).
    :return: A flat dictionary with dot-separated keys.
    """
    if result is None:
        result = {}

    for key, value in json_obj.items():
        new_key = f"{parent_key}.{key}" if parent_key else key
        if isinstance(value, list):
            for i, item in enumerate(value):
                if isinstance(item, dict):
                    flatten_json(item, f"{new_key}[{i}]", result)
                else:
                    result[f"{new_key}[{i}]"] = item
        elif isinstance(value, dict):
            flatten_json(value, new_key, result)
        else:
            result[new_key] = value

    return result

