class Matrix:
    def __init__(self, data):
        """
        Initializes the matrix with the given 2D list `data`.
        Raises ValueError if rows are not of the same length or elements are not numbers.
        """
        if not all(isinstance(row, list) and len(row) == len(data[0]) for row in data):
            raise ValueError("All rows must be lists of the same length.")
        if not all(isinstance(el, (int, float)) for row in data for el in row):
            raise ValueError("All elements must be integers or floats.")
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0])

    def add(self, other):
        """
        Adds another Matrix object to the current matrix.
        Raises ValueError if matrices do not have the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to add.")
        return Matrix([[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def subtract(self, other):
        """
        Subtracts another Matrix object from the current matrix.
        Raises ValueError if matrices do not have the same dimensions.
        """
        if not isinstance(other, Matrix) or self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must be of the same dimensions to subtract.")
        return Matrix([[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def multiply(self, other):
        """
        Multiplies the current matrix with another Matrix object.
        Raises ValueError if the number of columns in the current matrix is not equal to the number of rows in the other matrix.
        """
        if not isinstance(other, Matrix) or self.cols != other.rows:
            raise ValueError("Number of columns in the first matrix must be equal to the number of rows in the second.")
        result_data = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result_data)
