def generate_primes(n):
    """
    Generate a list of the first n prime numbers.

    Parameters:
    n (int): The number of prime numbers to generate.

    Returns:
    list: A list containing the first n prime numbers.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes
