def match_brackets(expression):
    """
    Determines if the brackets in the given expression are balanced.

    :param expression: A string containing only the characters '(', ')', '{', '}', '[' and ']'.
    :return: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False

    return not stack
