def find_max_prime(n):
    """
    Returns the largest prime number less than or equal to n.
    If no such prime number exists, returns None.

    :param n: int - the upper limit to search for the largest prime number
    :return: int or None - the largest prime number <= n or None if no prime exists
    """
    if n < 2:
        return None

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    for candidate in range(n, 1, -1):
        if is_prime(candidate):
            return candidate

    return None
