def sum_of_primes(n):
    """
    Calculate the sum of all prime numbers up to a given integer n.

    Parameters:
    n (int): The upper limit up to which prime numbers are summed.

    Returns:
    int: The sum of all prime numbers up to n.
    """
    if n < 2:
        return 0
    primes = [True] * (n + 1)
    primes[0], primes[1] = False, False

    for start in range(2, int(n**0.5) + 1):
        if primes[start]:
            for multiple in range(start*start, n + 1, start):
                primes[multiple] = False

    return sum(index for index, is_prime in enumerate(primes) if is_prime)
