def find_substrings(text, pattern):
    """
    Returns a list of starting indices of all occurrences of the pattern in the text.

    :param text: The string in which to search for the pattern.
    :param pattern: The substring pattern to search for in the text.
    :return: A list of starting indices where the pattern is found in the text.
    """
    n, m = len(text), len(pattern)
    indices = []

    if m == 0:
        return list(range(n + 1))
    if n == 0:
        return indices

    prime = 101
    d = 256
    h_pattern = 0
    h_text = 0
    h = 1

    for i in range(m - 1):
        h = (h * d) % prime

    for i in range(m):
        h_pattern = (d * h_pattern + ord(pattern[i])) % prime
        h_text = (d * h_text + ord(text[i])) % prime

    for i in range(n - m + 1):
        if h_pattern == h_text:
            if text[i:i+m] == pattern:
                indices.append(i)

        if i < n - m:
            h_text = (d * (h_text - ord(text[i]) * h) + ord(text[i + m])) % prime

            if h_text < 0:
                h_text += prime

    return indices
```

