        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add_to_end(self, data):
        """Adds a new node with the specified data to the end of the list."""
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def add_to_start(self, data):
        """Adds a new node with the specified data to the start of the list."""
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    def remove(self, key):
        """Removes the first node with the specified key from the list."""
        current_node = self.head

        if current_node and current_node.data == key:
            self.head = current_node.next
            current_node = None
            return

        previous_node = None
        while current_node and current_node.data != key:
            previous_node = current_node
            current_node = current_node.next

        if current_node is None:
            return

        previous_node.next = current_node.next
        current_node = None

    def retrieve_by_index(self, index):
        """Returns the data of the node at the specified index. If the index is out of bounds, return None."""
        current_node = self.head
        current_index = 0

        while current_node is not None:
            if current_index == index:
                return current_node.data
            current_index += 1
            current_node = current_node.next

        return None

    def display(self):
        """Prints the elements of the list in order, separated by ' -> ', and ending with 'None'."""
        current_node = self.head
        while current_node:
            print(current_node.data, end=" -> ")
            current_node = current_node.next
        print("None")
