class TaskStack:
    def __init__(self):
        """Initializes an empty stack."""
        self.stack = []

    def push(self, task):
        """Adds a task to the stack."""
        self.stack.append(task)

    def pop(self):
        """Removes and returns the top task from the stack. Returns None if the stack is empty."""
        if self.is_empty():
            return None
        return self.stack.pop()

    def peek(self):
        """Returns the top task from the stack without removing it. Returns None if the stack is empty."""
        if self.is_empty():
            return None
        return self.stack[-1]

    def is_empty(self):
        """Returns True if the stack is empty, and False otherwise."""
        return len(self.stack) == 0

    def size(self):
        """Returns the number of tasks in the stack."""
        return len(self.stack)
