def find_post(post_id):
    """
    Finds a post by its ID.

    :param post_id: The ID of the post to find.
    :return: The post if found, otherwise None.
    """
    return next((post for post in posts if post['id'] == post_id), None)

@app.route('/posts', methods=['POST'])
def create_post():
    """
    Creates a new post.

    :return: JSON response with the created post and status code 201.
    """
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'Title and content are required'}), 400

    new_post = {
        'id': len(posts) + 1,
        'title': data['title'],
        'content': data['content']
    }
    posts.append(new_post)
    return jsonify(new_post), 201

@app.route('/posts', methods=['GET'])
def read_posts():
    """
    Reads all posts.

    :return: JSON response with a list of all posts.
    """
    return jsonify(posts)

@app.route('/posts/<int:post_id>', methods=['PUT'])
def update_post(post_id):
    """
    Updates a post by its ID.

    :param post_id: The ID of the post to update.
    :return: JSON response with the updated post.
    """
    post = find_post(post_id)
    if post is None:
        return jsonify({'error': 'Post not found'}), 404

    data = request.get_json()
    if 'title' in data:
        post['title'] = data['title']
    if 'content' in data:
        post['content'] = data['content']

    return jsonify(post)

@app.route('/posts/<int:post_id>', methods=['DELETE'])
def delete_post(post_id):
    """
    Deletes a post by its ID.

    :param post_id: The ID of the post to delete.
    :return: JSON response with a success message.
    """
    global posts
    post = find_post(post_id)
    if post is None:
        return jsonify({'error': 'Post not found'}), 404

    posts = [p for p in posts if p['id'] != post_id]
    return jsonify({'message': 'Post deleted'})

