import random

def is_valid(board, row, col, num):
    """
    Check if placing num in board[row][col] is valid.
    """
    for x in range(4):
        if board[row][x] == num or board[x][col] == num or board[row - row % 2 + x // 2][col - col % 2 + x % 2] == num:
            return False
    return True

def solve_sudoku(board):
    """
    Solve the Sudoku puzzle using backtracking.
    """
    empty = find_empty_location(board)
    if not empty:
        return True  # Puzzle solved
    row, col = empty

    for num in random.sample(range(1, 5), 4):
        if is_valid(board, row, col, num):
            board[row][col] = num
            if solve_sudoku(board):
                return True
            board[row][col] = 0  # Backtrack

    return False

def find_empty_location(board):
    """
    Find an empty location in the board.
    """
    for i in range(4):
        for j in range(4):
            if board[i][j] == 0:
                return (i, j)
    return None

def is_unique_solution(board):
    """
    Check if the board has a unique solution.
    """
    solutions = []

    def solve_and_count_solutions(board):
        empty = find_empty_location(board)
        if not empty:
            solutions.append([row[:] for row in board])
            return True  # Puzzle solved

        row, col = empty
        for num in range(1, 5):
            if is_valid(board, row, col, num):
                board[row][col] = num
                solve_and_count_solutions(board)
                board[row][col] = 0  # Backtrack

    solve_and_count_solutions([row[:] for row in board])
    return len(solutions) == 1

def generate_sudoku():
    """
    Generate a random 4x4 Sudoku puzzle with a unique solution.
    """
    board = [[0] * 4 for _ in range(4)]
    solve_sudoku(board)  # Fill the board with a unique solution

    filled_cells = [(i, j) for i in range(4) for j in range(4)]
    random.shuffle(filled_cells)
    for i, j in filled_cells:
        temp = board[i][j]
        board[i][j] = 0
        if not is_unique_solution(board):
            board[i][j] = temp  # If removing this number makes multiple solutions, put it back

    return board

# Example usage
puzzle = generate_sudoku()
for row in puzzle:
    print(row)
