class Matrix:
    def __init__(self, data):
        self.data = data
        self.rows = len(data)
        self.cols = len(data[0]) if self.rows > 0 else 0

    def add(self, other):
        """
        Adds two matrices of the same dimensions.

        :param other: Another Matrix object to add to the current matrix.
        :return: A new Matrix object representing the sum of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for addition")
        result = [
            [self.data[i][j] + other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def subtract(self, other):
        """
        Subtracts another matrix from the current matrix.

        :param other: Another Matrix object to subtract from the current matrix.
        :return: A new Matrix object representing the difference of the two matrices.
        :raises ValueError: If the matrices do not have the same dimensions.
        """
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions for subtraction")
        result = [
            [self.data[i][j] - other.data[i][j] for j in range(self.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def multiply(self, other):
        """
        Multiplies the current matrix by another matrix.

        :param other: Another Matrix object to multiply with the current matrix.
        :return: A new Matrix object representing the product of the two matrices.
        :raises ValueError: If the number of columns in the first matrix is not equal to the number of rows in the second matrix.
        """
        if self.cols != other.rows:
            raise ValueError("Number of columns of first matrix must be equal to number of rows of second matrix for multiplication")
        result = [
            [sum(self.data[i][k] * other.data[k][j] for k in range(self.cols)) for j in range(other.cols)]
            for i in range(self.rows)
        ]
        return Matrix(result)

    def __str__(self):
        """
        Returns a string representation of the matrix.

        :return: A string with each row of the matrix separated by a newline and each element in a row separated by a tab.
        """
        return '\n'.join(['\t'.join(map(str, row)) for row in self.data])
