class BinaryTreeNode:
    def __init__(self, value):
        """
        Initialize a new binary tree node with the given value.

        :param value: The value to be stored in the node.
        """
        self.value = value
        self.left = None
        self.right = None

    def insert(self, value):
        """
        Insert a new value into the binary tree, maintaining the binary search tree property.

        :param value: The value to be inserted.
        """
        if value <= self.value:
            if self.left is None:
                self.left = BinaryTreeNode(value)
            else:
                self.left.insert(value)
        else:
            if self.right is None:
                self.right = BinaryTreeNode(value)
            else:
                self.right.insert(value)

    def in_order_traversal(self):
        """
        Perform an in-order traversal of the binary tree and return the values in a list.

        :return: A list of values in in-order traversal order.
        """
        traversal = []
        if self.left:
            traversal += self.left.in_order_traversal()
        traversal.append(self.value)
        if self.right:
            traversal += self.right.in_order_traversal()
        return traversal
