def quickselect(arr, left, right, k):
    """
    Select the k-th smallest element in arr[left:right+1] using the Quickselect algorithm.
    """
    if left == right:
        return arr[left]

    pivot_index = partition(arr, left, right)

    if k == pivot_index:
        return arr[k]
    elif k < pivot_index:
        return quickselect(arr, left, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, right, k)

def partition(arr, left, right):
    """
    Partition the array around a pivot element and return the final position of the pivot.
    """
    pivot = arr[right]
    i = left
    for j in range(left, right):
        if arr[j] < pivot:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
    arr[i], arr[right] = arr[right], arr[i]
    return i

def find_median(numbers):
    """
    Find and return the median of the list of numbers.
    """
    n = len(numbers)
    if n % 2 == 1:
        return quickselect(numbers, 0, n - 1, n // 2)
    else:
        left_median = quickselect(numbers, 0, n - 1, n // 2 - 1)
        right_median = quickselect(numbers, 0, n - 1, n // 2)
        return (left_median + right_median) / 2

