def convert_temperature(temp: float, unit_from: str, unit_to: str) -> float:
    """
    Convert a temperature from one unit to another.

    Parameters:
    temp (float): The temperature value to convert.
    unit_from (str): The unit of the input temperature ('C', 'F', 'K').
    unit_to (str): The unit of the output temperature ('C', 'F', 'K').

    Returns:
    float: The converted temperature.
    """
    # Convert all input units to uppercase to handle case sensitivity
    unit_from = unit_from.upper()
    unit_to = unit_to.upper()

    # Helper function to convert Celsius to other units
    def celsius_to(unit, temp_celsius):
        if unit == 'C':
            return temp_celsius
        elif unit == 'F':
            return temp_celsius * 9/5 + 32
        elif unit == 'K':
            return temp_celsius + 273.15

    # Helper function to convert Fahrenheit to other units
    def fahrenheit_to(unit, temp_fahrenheit):
        if unit == 'C':
            return (temp_fahrenheit - 32) * 5/9
        elif unit == 'F':
            return temp_fahrenheit
        elif unit == 'K':
            return (temp_fahrenheit - 32) * 5/9 + 273.15

    # Helper function to convert Kelvin to other units
    def kelvin_to(unit, temp_kelvin):
        if unit == 'C':
            return temp_kelvin - 273.15
        elif unit == 'F':
            return (temp_kelvin - 273.15) * 9/5 + 32
        elif unit == 'K':
            return temp_kelvin

    # Convert the input temperature to Celsius
    if unit_from == 'C':
        temp_celsius = temp
    elif unit_from == 'F':
        temp_celsius = fahrenheit_to('C', temp)
    elif unit_from == 'K':
        temp_celsius = kelvin_to('C', temp)
    else:
        raise ValueError(f"Unknown temperature unit: {unit_from}")

    # Convert the temperature from Celsius to the desired unit
    if unit_to == 'C':
        return celsius_to('C', temp_celsius)
    elif unit_to == 'F':
        return celsius_to('F', temp_celsius)
    elif unit_to == 'K':
        return celsius_to('K', temp_celsius)
    else:
        raise ValueError(f"Unknown temperature unit: {unit_to}")
