def count_unique_vowels(s: str) -> int:
    """
    Counts the number of unique vowels in the given string.

    :param s: A string consisting of lowercase English letters.
    :return: An integer representing the number of unique vowels in the string.
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    unique_vowels = set()

    for char in s:
        if char in vowels:
            unique_vowels.add(char)

    return len(unique_vowels)
