def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_max_prime(numbers):
    """Find the largest prime number in a list of integers."""
    max_prime = None
    for num in numbers:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num
    return max_prime

# Example usage:
numbers = [2, 3, 4, 5, 6, 7, 8, 9, 10]
print(find_max_prime(numbers))  # Output should be 7
