        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """
        Inserts a new value into the binary search tree.
        If the value already exists, do nothing.
        """
        if self.root is None:
            self.root = TreeNode(value)
        else:
            self._insert_recursively(self.root, value)

    def _insert_recursively(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._insert_recursively(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._insert_recursively(node.right, value)

    def search(self, value):
        """
        Returns True if the value exists in the tree, otherwise returns False.
        """
        return self._search_recursively(self.root, value)

    def _search_recursively(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        elif value < node.value:
            return self._search_recursively(node.left, value)
        else:
            return self._search_recursively(node.right, value)

    def in_order_traversal(self):
        """
        Returns a list of values in the tree in in-order traversal order.
        """
        return self._in_order_traversal_recursively(self.root)

    def _in_order_traversal_recursively(self, node):
        if node is None:
            return []
        return (self._in_order_traversal_recursively(node.left) +
                [node.value] +
                self._in_order_traversal_recursively(node.right))
